#!/usr/bin/env bash
# =============================================================================
#  CoreGSM installer  -  self-hosted game server status panel
#  Target: clean Debian 13 (trixie) / 12 (bookworm), run as root.
#
#  Interactive:      sudo bash install.sh
#  Non-interactive:  DOMAIN=gsm.example.com LE_EMAIL=me@example.com \
#                    sudo -E bash install.sh
#
#  This file is GENERATED by tools/build-installer.sh from the src/ directory.
#  Do not edit the embedded files here; edit src/ and rebuild.
# =============================================================================
set -Eeuo pipefail

# "su" without "-" keeps the caller's PATH, which lacks the sbin directories (ufw, sshd, ...)
export PATH="$PATH:/usr/local/sbin:/usr/sbin:/sbin"

# Install directory. Priority: APP_DIR from the environment, the directory remembered by a previous install
# (/etc/coregsm/app_dir), an older installation in /app, otherwise the default /opt/coregsm.
APP_DIR_FILE=/etc/coregsm/app_dir
APP_DIR_FIXED=0
if [ -n "${APP_DIR:-}" ]; then
  APP_DIR_FIXED=1
elif [ -s "$APP_DIR_FILE" ]; then
  APP_DIR="$(head -n1 "$APP_DIR_FILE")"; APP_DIR_FIXED=1
elif [ -f /app/.env ] && [ -f /app/docker-compose.yml ]; then
  APP_DIR=/app; APP_DIR_FIXED=1
else
  APP_DIR=/opt/coregsm
fi
# set by tools/build-installer.sh: hash of all files embedded below (compared with version.txt in the repo)
COREGSM_BUILD="@@BUILD_ID@@"
export DEBIAN_FRONTEND=noninteractive

# ---------- colours ----------
if [ -t 1 ]; then
  RED=$'\033[1;31m'; GREEN=$'\033[1;32m'; YELLOW=$'\033[1;33m'; BLUE=$'\033[1;34m'
  MAGENTA=$'\033[1;35m'; CYAN=$'\033[1;36m'; BOLD=$'\033[1m'; DIM=$'\033[2m'; NC=$'\033[0m'
else
  RED=''; GREEN=''; YELLOW=''; BLUE=''; MAGENTA=''; CYAN=''; BOLD=''; DIM=''; NC=''
fi
# set by issue_certificate / launch
CERT_MODE=""; CERT_CHANGED=0; CERT_ISSUED=0; PANEL_OK=0

LOGFILE="${COREGSM_LOG:-/var/log/coregsm-install.log}"
mkdir -p "$(dirname "$LOGFILE")" 2>/dev/null || true
# the log may contain proxy addresses: readable by root only, credentials are masked (see redact_log)
{ touch "$LOGFILE" && chmod 600 "$LOGFILE"; } 2>/dev/null || true
redact_log() { sed -i -E 's#(://)[^/@[:space:]]+@#\1***@#g' "$LOGFILE" 2>/dev/null || true; }
trap redact_log EXIT
APT_OPTS=(-o DPkg::Lock::Timeout=300)
IS_TTY=0; [ -t 1 ] && IS_TTY=1
# started by "coregsm update": print only the steps and their results
QUIET_OK="${COREGSM_FROM_MANAGER:-0}"
# COREGSM_VERBOSE=1: show the full output of apt/docker on the screen as well
VERBOSE="${COREGSM_VERBOSE:-0}"

# everything that is shown also goes to the log, without colour codes
logf() { printf '%s\n' "$*" | sed -E 's/\x1b\[[0-9;]*m//g; s#(://)[^/@[:space:]]+@#\1***@#g' >> "$LOGFILE" 2>/dev/null || true; }

STEP=0
TOTAL_STEPS=12
# Live progress for the panel's update bar: only while the manager runs the installer (COREGSM_FROM_MANAGER=1).
# Writes percent and "what is happening now" into status.json; the manager adds its own phases before (up to 20 %)
# and after (health check, 97-100 %).
progress() { # progress PERCENT "message"
  [ "${COREGSM_FROM_MANAGER:-0}" = 1 ] && [ -d "$APP_DIR/update" ] || return 0
  local msg rb=false; msg="$(printf '%s' "$2" | tr -d '\n\r' | sed 's/["\\]/ /g')"
  if declare -F rollback_available >/dev/null && rollback_available; then rb=true; fi
  printf '{"state":"running","message":"%s","time":%s000,"rollback_available":%s,"progress":%s}\n' "$msg" "$(date +%s)" "$rb" "$1" > "$APP_DIR/update/status.json.tmp" 2>/dev/null \
    && mv -f "$APP_DIR/update/status.json.tmp" "$APP_DIR/update/status.json" 2>/dev/null || true
  chmod 644 "$APP_DIR/update/status.json" 2>/dev/null || true
}
step_pct() { # the share of the whole update that each installer step has reached when it starts
  case "$*" in
    "Проверка окружения"*) echo 22 ;;
    "Прокси"*) echo 24 ;;
    "Обновление системы"*) echo 26 ;;
    "Установка curl"*) echo 28 ;;
    "Установка Docker"*) echo 30 ;;
    "Настройка файрвола"*|"Настройка"*) echo 32 ;;
    "Создание файлов проекта"*) echo 36 ;;
    "Генерация секретов"*) echo 40 ;;
    "Сборка образов"*) echo 44 ;;
    "SSL-сертификат"*|"Выпуск SSL"*) echo 82 ;;
    "Запуск контейнеров"*) echo 88 ;;
    *) echo "" ;;
  esac
}
step()  {
  STEP=$((STEP + 1)); echo -e "\n${BLUE}[${STEP}/${TOTAL_STEPS}]${NC} ${BOLD}$*${NC}"; logf "[${STEP}/${TOTAL_STEPS}] $*"
  local p; p="$(step_pct "$*")"
  [ -z "$p" ] || progress "$p" "$*"
}
info()  { [ "$QUIET_OK" = 1 ] || echo -e "  ${CYAN}>${NC} $*"; logf "  > $*"; }
ok()    { [ "$QUIET_OK" = 1 ] || echo -e "  ${GREEN}✔${NC} $*"; logf "  ok: $*"; }
done_line() { echo -e "  ${GREEN}✔${NC} $*"; logf "  ok: $*"; }
warn()  { echo -e "  ${YELLOW}!${NC} $*"; logf "  warn: $*"; }
die()   { echo -e "\n${RED}✖ $*${NC}" >&2; logf "FATAL: $*"; exit 1; }

trap 'logf "ERROR line ${LINENO}: ${BASH_COMMAND}"; echo -e "\n${RED}✖ Установка прервана на строке ${LINENO}: ${BASH_COMMAND}${NC}\n  Подробности: ${LOGFILE}" >&2' ERR

# Runs a long command quietly: the full output goes to the log, the screen shows a spinner and one result line.
# _run "message" command...   returns the exit code of the command
_run() {
  local msg="$1"; shift
  local t0=$SECONDS rc=0 pid i=0
  local frames=(⠋ ⠙ ⠹ ⠸ ⠼ ⠴ ⠦ ⠧ ⠇ ⠏)
  printf '\n### %s: %s\n' "$msg" "$*" | sed -E 's#(://)[^/@[:space:]]+@#\1***@#g' >> "$LOGFILE" 2>/dev/null || true
  if [ "$VERBOSE" = 1 ]; then
    echo -e "  ${CYAN}›${NC} $msg"
    set +e; "$@" 2>&1 | tee -a "$LOGFILE"; rc=${PIPESTATUS[0]}; set -e
  elif [ "$IS_TTY" = 1 ]; then
    "$@" >> "$LOGFILE" 2>&1 &
    pid=$!
    while kill -0 "$pid" 2>/dev/null; do
      printf '\r  %s%s%s %s %s%ds%s\033[K' "$CYAN" "${frames[i % 10]}" "$NC" "$msg" "$DIM" $((SECONDS - t0)) "$NC"
      i=$((i + 1)); sleep 0.12
    done
    wait "$pid" || rc=$?
    printf '\r\033[K'
  else
    echo "  … $msg"
    "$@" >> "$LOGFILE" 2>&1 || rc=$?
  fi
  redact_log
  if [ "$rc" -eq 0 ]; then
    done_line "$msg ${DIM}($((SECONDS - t0)) с)${NC}"
    return 0
  fi
  echo -e "  ${RED}✖${NC} $msg" >&2
  logf "  FAILED (код $rc): $msg"
  return "$rc"
}
# run: stop the installer on failure and show the tail of the log; run_soft: just report the exit code
run() {
  _run "$@" || {
    echo -e "${DIM}$(tail -n 20 "$LOGFILE" 2>/dev/null | sed 's/^/    /')${NC}" >&2
    die "Не удалось: $1. Полный журнал: $LOGFILE"
  }
}
run_soft() { _run "$@"; }

