# LOGO-END

# The project logo as terminal art with the name and a tagline next to it. It needs a true-colour terminal;
# otherwise (NO_COLOR, no colour support, output not a terminal) the plain text banner is shown.
logo_ok() {
  [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && case "${COLORTERM:-}" in truecolor|24bit) return 0 ;; *) return 1 ;; esac
}
banner() {
  if logo_ok; then
    local i row text
    echo
    for i in "${!logo_rows_large[@]}"; do
      row="${logo_rows_large[$i]}"
      case "$i" in
        4) text="${BOLD}${MAGENTA}CoreGSM${NC}" ;;
        5) text="${DIM}панель мониторинга игровых серверов${NC}" ;;
        6) text="${DIM}и сообщений для Discord${NC}" ;;
        8) text="${DIM}сборка ${COREGSM_BUILD:-}${NC}" ;;
        *) text='' ;;
      esac
      printf '  %b   %b\n' "$row" "$text"
    done
    echo
  else
    echo -e "${MAGENTA}"
    cat << 'ART'
   ____                 ____ ____  __  __
  / ___|___  _ __ ___  / ___/ ___||  \/  |
 | |   / _ \| '__/ _ \| |  _\___ \| |\/| |
 | |__| (_) | | |  __/| |_| |___) | |  | |
  \____\___/|_|  \___| \____|____/|_|  |_|
ART
    echo -e "${NC}${DIM}  self-hosted game server status panel + Discord cards${NC}"
  fi
}

# Read from the terminal even when the script is piped (curl ... | bash).
ask() { # ask VAR "Prompt" [default] [secret]
  local __var="$1" __prompt="$2" __def="${3:-}" __secret="${4:-}" __val=""
  if [ -n "${!__var:-}" ]; then return 0; fi
  # Never prompt when there is no usable terminal: the update button in the panel (systemd), cron,
  # or "coregsm update". /dev/tty may exist as a file yet fail to open ("No such device or address"),
  # so test that it can really be opened instead of just being readable.
  if [ "${COREGSM_FROM_MANAGER:-}" = 1 ] || ! { : < /dev/tty; } 2>/dev/null; then
    [ -n "$__def" ] && { printf -v "$__var" '%s' "$__def"; return 0; }
    die "Нет терминала для ввода. Передайте $__var через переменную окружения или впишите в $APP_DIR/.env"
  fi
  if [ -n "$__def" ]; then __prompt="$__prompt [${__def}]"; fi
  if [ -n "$__secret" ]; then
    read -r -s -p "  ${BOLD}${__prompt}:${NC} " __val < /dev/tty; echo
  else
    read -r -p "  ${BOLD}${__prompt}:${NC} " __val < /dev/tty
  fi
  printf -v "$__var" '%s' "${__val:-$__def}"
}

gen_secret() { # gen_secret LENGTH  -> alphanumeric
  local n="$1" s=""
  while [ "${#s}" -lt "$n" ]; do
    s+="$(openssl rand -base64 48 | tr -dc 'A-Za-z0-9')"
  done
  printf '%s' "${s:0:$n}"
}

env_get() { # env_get KEY  -> value from existing .env (empty if none)
  [ -f "$APP_DIR/.env" ] || return 0
  grep -E "^$1=" "$APP_DIR/.env" | tail -n1 | cut -d= -f2- || true
}

env_set() { # env_set KEY VALUE  -> replaces or appends the line in .env, keeping everything else (and the file mode)
  local f="$APP_DIR/.env" tmp
  [ -f "$f" ] || return 0
  tmp="$(mktemp)"
  if grep -qE "^$1=" "$f"; then
    K="$1" V="$2" awk 'BEGIN{k=ENVIRON["K"]; v=ENVIRON["V"]} index($0, k "=") == 1 {print k "=" v; next} {print}' "$f" > "$tmp"
  else
    { cat "$f"; printf '%s=%s\n' "$1" "$2"; } > "$tmp"
  fi
  cat "$tmp" > "$f"
  rm -f "$tmp"
}

# Is a CoreGSM stack running right now? (then an update must not stop it)
stack_running() {
  [ -f "$APP_DIR/docker-compose.yml" ] || return 1
  (cd "$APP_DIR" && docker compose ps --status running -q 2>/dev/null | grep -q .)
}
service_running() { # service_running NAME
  [ -f "$APP_DIR/docker-compose.yml" ] || return 1
  (cd "$APP_DIR" && docker compose ps --status running --services 2>/dev/null | grep -qx "$1")
}

# ---------- 1. preflight ----------
preflight() {
  step "Проверка окружения"
  [ "$(id -u)" -eq 0 ] || die "Запустите скрипт от root: sudo bash install.sh"
  [ -r /etc/os-release ] || die "Не удалось определить ОС"
  # shellcheck disable=SC1091
  . /etc/os-release
  [ "${ID:-}" = "debian" ] || warn "Скрипт рассчитан на Debian, обнаружено: ${PRETTY_NAME:-unknown}"
  case "${VERSION_ID:-}" in
    12|13) ok "ОС: ${PRETTY_NAME}" ;;
    *) warn "ОС ${PRETTY_NAME:-unknown} не проверялась (ожидается Debian 12/13). Продолжаю." ;;
  esac
  CODENAME="${VERSION_CODENAME:-bookworm}"
  case "$(uname -m)" in
    x86_64|aarch64) ok "Архитектура: $(uname -m)" ;;
    *) die "Неподдерживаемая архитектура: $(uname -m)" ;;
  esac

  local mem_mb disk_mb busy
  mem_mb="$(awk '/MemTotal/{print int($2/1024)}' /proc/meminfo)"
  # On a system that already runs CoreGSM (update/reinstall) low resources only produce warnings:
  # the images exist, and a real shortage will show up as a clear build error with the cause in the log.
  local reinstall=0
  [ -f "$APP_DIR/docker-compose.yml" ] && reinstall=1
  if [ "$mem_mb" -lt 900 ] && [ "$reinstall" = 0 ]; then
    die "Недостаточно памяти: ${mem_mb} МБ (нужно от 1 ГБ, лучше 2 ГБ)"
  elif [ "$mem_mb" -lt 1800 ]; then
    warn "Памяти ${mem_mb} МБ: сборка образов может идти долго. Рекомендуется 2 ГБ"
  else
    ok "Память: ${mem_mb} МБ"
  fi
  disk_mb="$(df -Pm / | awk 'NR==2{print $4}')"
  if [ "$disk_mb" -lt 3000 ] && [ "$reinstall" = 0 ]; then
    die "Мало места на диске: свободно ${disk_mb} МБ (нужно от 3 ГБ)"
  elif [ "$disk_mb" -lt 1500 ]; then
    warn "Свободно только ${disk_mb} МБ: сборка образов может не поместиться. Очистить место: docker system prune -f"
  else
    ok "Диск: свободно ${disk_mb} МБ"
  fi
  # ports 80/443: skipped on a reinstall, where our own containers hold them
  if [ ! -f "$APP_DIR/docker-compose.yml" ]; then
    busy="$(ss -ltnH 'sport = :80 or sport = :443' 2>/dev/null | awk '{print $4}' | tr '\n' ' ' || true)"
    [ -z "$busy" ] || die "Порты 80/443 уже заняты ($busy). Остановите другой веб-сервер (nginx, apache) и запустите установку снова"
  fi
}

# ---------- 0. where to install ----------
choose_install_dir() {
  local dir=""
  if [ "$APP_DIR_FIXED" = 1 ]; then
    dir="$APP_DIR"
  else
    # a fresh server: say where everything goes and let the user change it
    ask dir "Папка установки (там будут конфигурация, сертификаты и копии)" "$APP_DIR"
  fi
  dir="${dir%/}"
  case "$dir" in
    /|/bin|/boot|/dev|/etc|/home|/lib*|/proc|/root|/run|/sbin|/sys|/tmp|/usr|/usr/*|/var|/var/lib|/var/lib/docker*)
      die "Папка установки \"$dir\" недопустима. Выберите отдельную папку, например /opt/coregsm" ;;
  esac
  [[ "$dir" =~ ^/[A-Za-z0-9._/-]+$ ]] || die "Папка установки должна быть абсолютным путём из латинских букв, цифр, точки, дефиса и подчёркивания (например /opt/coregsm)"
  if [ -e "$dir" ] && [ ! -d "$dir" ]; then die "$dir существует и не является папкой"; fi
  if [ -d "$dir" ] && [ -n "$(ls -A "$dir" 2>/dev/null)" ] && [ ! -f "$dir/docker-compose.yml" ]; then
    die "Папка $dir не пуста и не содержит установку CoreGSM. Укажите пустую или несуществующую папку"
  fi
  APP_DIR="$dir"
  export APP_DIR
  ok "Папка установки: $APP_DIR"
}

# ---------- 1b. proxy (optional) ----------
PROXY_MARK="# managed by CoreGSM installer"

# Accepts socks5://, socks5h://, http://, https:// (optionally with user:pass@)
valid_proxy() { [[ "$1" =~ ^(socks5h?|http|https)://([^@/[:space:]]+@)?[^@/:[:space:]]+:[0-9]{1,5}/?$ ]]; }

setup_proxy() {
  step "Прокси (необязательно)"
  : "${PROXY_URL:=$(env_get PROXY_URL)}"
  echo -e "  ${DIM}Если задан, через прокси пойдут: бот → Discord, apt, curl, загрузка образов Docker.${NC}"
  echo -e "  ${DIM}Формат: socks5://[user:pass@]host:1080  или  http://[user:pass@]host:3128${NC}"
  echo -e "  ${DIM}Опрос игровых серверов (UDP/TCP query) всегда идёт напрямую.${NC}\n"
  ask PROXY_URL "Прокси (Enter — без прокси)" "-"
  [ "$PROXY_URL" = "-" ] && PROXY_URL=""
  BUILD_PROXY=""

  if [ -z "$PROXY_URL" ]; then
    ok "Прокси не используется"
    if grep -qs "$PROXY_MARK" /etc/apt/apt.conf.d/99coregsm-proxy; then rm -f /etc/apt/apt.conf.d/99coregsm-proxy; fi
    return 0
  fi

  valid_proxy "$PROXY_URL" || die "Некорректный адрес прокси: $PROXY_URL (пример: socks5://127.0.0.1:1080)"
  # SOCKS: resolve hostnames on the proxy side (socks5h) for curl/apt
  local tool_proxy="${PROXY_URL/#socks5:/socks5h:}"
  export http_proxy="$tool_proxy" https_proxy="$tool_proxy" all_proxy="$tool_proxy"
  export HTTP_PROXY="$tool_proxy" HTTPS_PROXY="$tool_proxy" ALL_PROXY="$tool_proxy"
  export no_proxy="localhost,127.0.0.1,::1" NO_PROXY="localhost,127.0.0.1,::1"

  ( umask 077; printf '%s\nAcquire::http::Proxy "%s";\nAcquire::https::Proxy "%s";\n' "$PROXY_MARK" "$tool_proxy" "$tool_proxy" \
    > /etc/apt/apt.conf.d/99coregsm-proxy )
  chmod 600 /etc/apt/apt.conf.d/99coregsm-proxy

  if curl -fsS --max-time 15 -o /dev/null https://download.docker.com/linux/debian/gpg; then
    ok "Прокси работает"
  else
    die "Прокси недоступен или не пускает наружу: проверьте адрес, логин и пароль"
  fi

  case "$PROXY_URL" in
    http://*|https://*) BUILD_PROXY="$PROXY_URL" ;;
    *) warn "SOCKS5: npm и certbot внутри Docker не умеют SOCKS, поэтому сборка образов и продление сертификата идут напрямую." ;;
  esac
}

# The Docker daemon (image pulls) reads HTTP(S)_PROXY from a systemd drop-in; Go also accepts socks5:// there.
configure_docker_proxy() {
  local dir=/etc/systemd/system/docker.service.d
  local file=$dir/coregsm-proxy.conf tmp
  tmp="$(mktemp)"
  if [ -n "${PROXY_URL:-}" ]; then
    printf '%s\n[Service]\nEnvironment="HTTP_PROXY=%s"\nEnvironment="HTTPS_PROXY=%s"\nEnvironment="NO_PROXY=localhost,127.0.0.1,::1"\n' \
      "$PROXY_MARK" "$PROXY_URL" "$PROXY_URL" > "$tmp"
    mkdir -p "$dir"
    if ! cmp -s "$tmp" "$file"; then
      install -m 0600 "$tmp" "$file"
      systemctl daemon-reload
      systemctl restart docker
      ok "Docker настроен на работу через прокси"
    fi
    chmod 600 "$file" 2>/dev/null || true
  elif grep -qs "$PROXY_MARK" "$file"; then
    rm -f "$file"
    systemctl daemon-reload
    systemctl restart docker
    ok "Прокси для Docker отключён"
  fi
  rm -f "$tmp"
}

# ---------- 2. system update ----------
system_update() {
  step "Обновление системы"
  if [ "${SKIP_UPDATE:-}" = "1" ]; then
    run "Обновление списка пакетов" apt-get "${APT_OPTS[@]}" update -y
    ok "SKIP_UPDATE=1: полное обновление пропущено (список пакетов обновлён)"
    return 0
  fi
  run "Обновление списка пакетов" apt-get "${APT_OPTS[@]}" update -y
  # a half-configured package from an earlier failed run would break every later apt call
  apt_repair
  preseed_grub
  if run_soft "Установка обновлений системы (несколько минут)" apt-get "${APT_OPTS[@]}" upgrade -y -o Dpkg::Options::=--force-confold -o Dpkg::Options::=--force-confdef; then
    ok "Система обновлена"
    return 0
  fi
  warn "Обновление системы завершилось с ошибкой, пробую починить dpkg и повторить"
  if apt_repair && run_soft "Повторная установка обновлений" apt-get "${APT_OPTS[@]}" upgrade -y -o Dpkg::Options::=--force-confold -o Dpkg::Options::=--force-confdef; then
    ok "Система обновлена"
    return 0
  fi
  # The panel does not need the system upgrade (usually a kernel or bootloader package that cannot be configured
  # inside a hosting VM). Keep the broken packages out of the way and carry on with the installation.
  apt_repair || true
  if dpkg --audit 2>/dev/null | grep -q .; then
    # still half-configured: hold those packages so the next apt-get install does not trip over them
    local bad; bad="$(dpkg --audit 2>/dev/null | awk '/^ / && NF {print $1}' | sort -u)"
    [ -z "$bad" ] || apt-mark hold $bad >> "$LOGFILE" 2>&1 || true
    dpkg --configure -a --force-confold >> "$LOGFILE" 2>&1 || true
  fi
  warn "Обновление системы пропущено из-за ошибки (см. $LOGFILE). Установка панели продолжается; обновите систему позже вручную: apt-get -f install && apt-get upgrade"
}

# Finishes interrupted package configuration and fixes broken dependencies. Returns 0 when apt is healthy again.
apt_repair() {
  run_soft "Починка незавершённой настройки пакетов" dpkg --configure -a --force-confold --force-confdef || true
  run_soft "Починка зависимостей" apt-get "${APT_OPTS[@]}" -f install -y -o Dpkg::Options::=--force-confold -o Dpkg::Options::=--force-confdef
}

# grub-pc asks "where to install GRUB" through debconf. Without a terminal there is no answer, its postinst fails
# and dpkg stops the whole upgrade (typical on VPS images). Answer in advance: the disk holding /, else "none".
preseed_grub() {
  dpkg -s grub-pc >/dev/null 2>&1 || return 0
  command -v debconf-set-selections >/dev/null 2>&1 || return 0
  local src disk=""
  src="$(findmnt -no SOURCE / 2>/dev/null || true)"
  if [ -b "$src" ]; then
    # walk up from the root device (partition, LVM, crypt...) to the physical disk, never a partition
    disk="$(lsblk -nds -o NAME,TYPE "$src" 2>/dev/null | awk '$2 == "disk" {print $1; exit}')"
    [ -n "$disk" ] && disk="/dev/$disk"
  fi
  if [ -n "$disk" ] && [ -b "$disk" ]; then
    echo "grub-pc grub-pc/install_devices multiselect $disk" | debconf-set-selections
    echo "grub-pc grub-pc/install_devices_empty boolean false" | debconf-set-selections
    info "GRUB: загрузчик обновляется на $disk"
  else
    echo "grub-pc grub-pc/install_devices_empty boolean true" | debconf-set-selections
    echo "grub-pc grub-pc/install_devices multiselect" | debconf-set-selections
    info "GRUB: диск не определён, установка загрузчика пропущена (на VPS загрузчик обычно ведёт хостер)"
  fi
}

# ---------- 3. packages ----------
base_packages() {
  step "Установка curl, git, ufw и вспомогательных пакетов"
  run "Установка curl, git, ufw" apt-get "${APT_OPTS[@]}" install -y --no-install-recommends curl git ufw ca-certificates gnupg openssl
  ok "Базовые пакеты установлены"
}

# ---------- 4. docker ----------
install_docker() {
  step "Установка Docker Engine и Docker Compose (docker.com)"
  if command -v docker >/dev/null 2>&1 && docker compose version >/dev/null 2>&1; then
    ok "Docker уже установлен: $(docker --version)"
    configure_docker_proxy
    return 0
  fi
  install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/debian/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  echo "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/debian ${CODENAME} stable" \
    > /etc/apt/sources.list.d/docker.list
  run "Обновление списка пакетов Docker" apt-get "${APT_OPTS[@]}" update -y
  run "Установка Docker Engine (1-2 минуты)" apt-get "${APT_OPTS[@]}" install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  systemctl enable --now docker
  docker compose version >/dev/null 2>&1 || die "Docker Compose не установился"
  ok "Установлено: $(docker --version)"
  configure_docker_proxy
}

# ---------- 5. questions ----------
collect_input() {
  step "Настройка"
  echo -e "  ${DIM}Нужен домен с A-записью на этот сервер и e-mail для Let's Encrypt.${NC}"
  echo -e "  ${DIM}Для локальной сети достаточно IP-адреса. Токен бота и администратора вы зададите в браузере.${NC}\n"

  : "${DISCORD_TOKEN:=$(env_get DISCORD_TOKEN)}"
  : "${DOMAIN:=$(env_get DOMAIN)}"
  : "${LE_EMAIL:=$(env_get LE_EMAIL)}"
  local prev_domain; prev_domain="$(env_get DOMAIN)"

  ask DOMAIN "Домен (gsm.my-domain.com) или IP сервера для локальной сети (192.168.88.152)"
  DOMAIN="$(printf '%s' "$DOMAIN" | tr '[:upper:]' '[:lower:]')"
  # the local mode chosen at the first install sticks to the same address: later updates must not
  # try Let's Encrypt for a local name. A different address is decided afresh.
  if [ -z "${LOCAL_MODE:-}" ] && [ "$DOMAIN" = "$prev_domain" ]; then LOCAL_MODE="$(env_get LOCAL_MODE)"; fi

  if [ "${LOCAL_MODE:-}" = "1" ] || is_local_host "$DOMAIN"; then
    # Local / development: Let's Encrypt cannot issue certificates for IPs and private names.
    LOCAL_MODE=1
    [[ "$DOMAIN" =~ ^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$ ]] || die "Некорректный адрес: $DOMAIN"
    LE_EMAIL=""
    ok "Локальный режим: $DOMAIN (самоподписанный сертификат, без Let's Encrypt)"
    return 0
  fi

  [[ "$DOMAIN" =~ ^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$ ]] || die "Некорректное доменное имя: $DOMAIN"

  ask LE_EMAIL "E-mail для Let's Encrypt"
  [[ "$LE_EMAIL" =~ ^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$ ]] || die "Некорректный e-mail: $LE_EMAIL"

  ok "Домен: $DOMAIN, e-mail: $LE_EMAIL"

  # DNS sanity check (warning only)
  local server_ip dns_ip
  server_ip="$(curl -4 -fsS --noproxy "*" --max-time 8 https://api.ipify.org 2>/dev/null || true)"
  dns_ip="$(getent ahostsv4 "$DOMAIN" 2>/dev/null | awk 'NR==1{print $1}' || true)"
  if [ -z "$dns_ip" ]; then
    warn "Домен $DOMAIN пока не резолвится. Выпуск сертификата, скорее всего, не удастся."
  elif [ -n "$server_ip" ] && [ "$dns_ip" != "$server_ip" ]; then
    warn "A-запись $DOMAIN указывает на $dns_ip, а IP сервера: $server_ip."
  else
    ok "DNS: $DOMAIN → ${dns_ip}"
  fi
}

# IPv4 address, "localhost", or a private suffix: Let's Encrypt is impossible for these.
is_local_host() {
  [[ "$1" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] && return 0
  [[ "$1" =~ (^localhost$|\.(local|lan|home|internal|test|localdomain)$|\.home\.arpa$) ]] && return 0
  return 1
}

# ---------- 6. firewall ----------
setup_firewall() {
  step "Настройка файрвола UFW"
  local ssh_port
  ssh_port="$( (sshd -T 2>/dev/null | awk '/^port /{print $2; exit}') || true)"
  [ -n "$ssh_port" ] || ssh_port="$(grep -hEi '^\s*Port\s+[0-9]+' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2>/dev/null | awk 'NR==1{print $2}' || true)"
  [ -n "$ssh_port" ] || ssh_port=22

  ufw default deny incoming >/dev/null
  ufw default allow outgoing >/dev/null
  ufw allow "${ssh_port}/tcp" comment 'SSH' >/dev/null
  ufw allow 80/tcp comment 'HTTP / ACME' >/dev/null
  ufw allow 443/tcp comment 'HTTPS' >/dev/null
  ufw --force enable >/dev/null
  ok "Открыты порты: SSH (${ssh_port}), 80, 443. Все остальные входящие закрыты."
  info "Порты backend (3000), frontend и бота наружу не публикуются: они доступны только внутри сети Docker."
}

# ---------- 7. project files ----------
@@GENERATE_FUNCTION@@

write_env() {
  step "Генерация секретов и .env"
  local jwt internal secrets_key
  SETUP_TOKEN="$(env_get SETUP_TOKEN)"; [ -n "$SETUP_TOKEN" ] || SETUP_TOKEN="$(gen_secret 16)"
  jwt="$(env_get JWT_SECRET)";          [ -n "$jwt" ]      || jwt="$(gen_secret 64)"
  internal="$(env_get INTERNAL_TOKEN)"; [ -n "$internal" ] || internal="$(gen_secret 48)"
  # a key of its own for the secrets in the database: JWT_SECRET can then be changed without losing them. An older
  # installation gets one on its next update; the backend writes its stored secrets again with it at start.
  secrets_key="$(env_get SECRETS_KEY)"; [ -n "$secrets_key" ] || secrets_key="$(gen_secret 64)"
  local poll lm cert_mode extra="" known='DOMAIN|LE_EMAIL|DISCORD_TOKEN|PROXY_URL|BUILD_PROXY|APP_VERSION|SETUP_TOKEN|JWT_SECRET|INTERNAL_TOKEN|SECRETS_KEY|POLL_INTERVAL_SEC|LOCAL_MODE|CERT_MODE'
  # the .env is truncated by the redirection below, so everything is read from it first
  local appver; appver="$(env_get APP_VERSION)"
  poll="$(env_get POLL_INTERVAL_SEC)"; [ -n "$poll" ] || poll=30
  lm=0; [ "${LOCAL_MODE:-}" = "1" ] && lm=1
  cert_mode="$(env_get CERT_MODE)"; [ "$lm" = 1 ] && [ -z "$cert_mode" ] && cert_mode=local
  # settings added by hand (custom variables) survive a re-run
  if [ -f "$APP_DIR/.env" ]; then
    extra="$(grep -E '^[A-Za-z_][A-Za-z0-9_]*=' "$APP_DIR/.env" | grep -Ev "^($known)=" || true)"
  fi
  umask 077
  cat > "$APP_DIR/.env" << ENVFILE
# Generated by CoreGSM installer. Keep this file private (chmod 600).
DOMAIN=${DOMAIN}
LE_EMAIL=${LE_EMAIL}
# optional first-start defaults; afterwards the token and proxy are managed in the web panel (Settings)
DISCORD_TOKEN=${DISCORD_TOKEN:-}
# socks5://[user:pass@]host:port or http://[user:pass@]host:port; empty = no proxy
PROXY_URL=${PROXY_URL:-}
# http(s) proxy for Docker image builds and certbot renewal (SOCKS is not supported there)
BUILD_PROXY=${BUILD_PROXY:-}
# installed build, compared with version.txt in the repository. The new value is written only after
# the panel has answered (see promote_version), so a failed update does not look like a finished one.
APP_VERSION=${appver}
# local mode (self-signed certificate, no Let's Encrypt) and the kind of the current certificate
LOCAL_MODE=${lm}
CERT_MODE=${cert_mode}
# one-time code for the first-run setup wizard in the browser
SETUP_TOKEN=${SETUP_TOKEN}
JWT_SECRET=${jwt}
INTERNAL_TOKEN=${internal}
# encrypts the Discord token, SMTP password and other secrets stored in the database; keep it with the database
# backups (the backup archive of the coregsm command includes it). Do not change it: the secrets become unreadable.
SECRETS_KEY=${secrets_key}
POLL_INTERVAL_SEC=${poll}
ENVFILE
  if [ -n "$extra" ]; then printf '# custom settings (kept on re-install)\n%s\n' "$extra" >> "$APP_DIR/.env"; fi
  chmod 600 "$APP_DIR/.env"
  umask 022
  ok "Секреты записаны в $APP_DIR/.env (права 600)"
}

# ---------- 8. TLS ----------
issue_certificate() {
  local conf="$APP_DIR/certbot/conf" live="$APP_DIR/certbot/conf/live/$DOMAIN"
  mkdir -p "$conf" "$APP_DIR/certbot/www"

  if [ "${LOCAL_MODE:-}" = "1" ]; then
    step "SSL-сертификат для локального режима (самоподписанный)"
    # an existing self-signed certificate that is valid for more than 30 days is kept: browsers that
    # already trusted it keep working, and nothing has to be restarted
    if [ -f "$live/.selfsigned" ] && [ -f "$live/fullchain.pem" ] && [ -f "$live/privkey.pem" ] \
       && openssl x509 -checkend $((30 * 86400)) -noout -in "$live/fullchain.pem" >/dev/null 2>&1; then
      CERT_MODE="local"
      ok "Самоподписанный сертификат ещё действует более 30 дней, оставляю прежний"
      return 0
    fi
    rm -rf "$live"
    mkdir -p "$live"
    CERT_CHANGED=1
    local san="DNS:${DOMAIN}"
    [[ "$DOMAIN" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] && san="IP:${DOMAIN}"
    openssl req -x509 -nodes -newkey rsa:2048 -days 825 -subj "/CN=${DOMAIN}" -addext "subjectAltName=${san}" \
      -keyout "$live/privkey.pem" -out "$live/fullchain.pem" >/dev/null 2>&1
    touch "$live/.selfsigned"
    CERT_MODE="local"
    ok "Сертификат создан (825 дней). Браузер покажет предупреждение: это ожидаемо."
    return 0
  fi

  step "Выпуск SSL-сертификата Let's Encrypt (Certbot в Docker)"

  if [ ! -f "$live/.selfsigned" ] && [ -f "$live/fullchain.pem" ]; then
    ok "Действующий сертификат для $DOMAIN уже есть, выпуск пропущен"
    CERT_MODE="letsencrypt"
    return 0
  fi

  # A temporary self-signed certificate is replaced: it is moved aside first (nginx keeps serving it from
  # memory) and put back if the issuance fails.
  local aside="$conf/live/$DOMAIN.selfsigned-bak" acme=(--standalone)
  if [ -f "$live/.selfsigned" ]; then
    rm -rf "$aside"; mv "$live" "$aside"
    rm -rf "$conf/archive/$DOMAIN" "$conf/renewal/$DOMAIN.conf"
  fi

  if service_running nginx-proxy; then
    # a running panel already answers on port 80: prove the domain through its webroot, no downtime
    acme=(--webroot -w /var/www/certbot)
    info "Панель работает: подтверждаю домен через неё, остановка не нужна"
  else
    # nothing serves port 80 (fresh install or stopped stack); a crash-looping nginx must not hold it
    if [ -f "$APP_DIR/docker-compose.yml" ]; then
      (cd "$APP_DIR" && docker compose stop nginx-proxy >/dev/null 2>&1) || true
    fi
  fi
  local pflag=()
  if [ "${acme[0]}" = "--standalone" ]; then pflag=(-p 80:80); fi

  if run_soft "Выпуск сертификата Let's Encrypt" docker run --rm ${pflag[@]+"${pflag[@]}"} ${BUILD_PROXY:+-e HTTPS_PROXY=$BUILD_PROXY} \
      -v "$conf:/etc/letsencrypt" -v "$APP_DIR/certbot/www:/var/www/certbot" \
      certbot/certbot certonly "${acme[@]}" --non-interactive --agree-tos --no-eff-email \
      -m "$LE_EMAIL" -d "$DOMAIN"; then
    CERT_MODE="letsencrypt"; CERT_CHANGED=1; CERT_ISSUED=1
    rm -rf "$aside"
    ok "Сертификат Let's Encrypt выпущен. Автопродление: контейнер certbot."
  else
    warn "Не удалось получить сертификат (проверьте A-запись домена и доступность порта 80)."
    if [ -d "$aside" ]; then
      rm -rf "$live"; mv "$aside" "$live"
      warn "Оставляю прежний самоподписанный сертификат."
      CERT_MODE="selfsigned"
      return 0
    fi
    warn "Создаю временный самоподписанный сертификат, чтобы панель всё равно запустилась."
    CERT_CHANGED=1
    mkdir -p "$live"
    openssl req -x509 -nodes -newkey rsa:2048 -days 30 -subj "/CN=${DOMAIN}" \
      -keyout "$live/privkey.pem" -out "$live/fullchain.pem" >/dev/null 2>&1
    touch "$live/.selfsigned"
    CERT_MODE="selfsigned"
  fi
}

# ---------- 9. launch ----------
# Images are built first, while the old containers keep serving. A failed build stops the installer here
# (die) and leaves the running version untouched.
build_images() {
  step "Сборка образов"
  cd "$APP_DIR"
  if stack_running; then info "Панель продолжает работать на прежней версии, пока идёт сборка."; fi
  # the build is the longest part and prints nothing useful: creep the bar from 44 % towards 80 % with the time
  local parent=$$ tick=0
  (
    t=0
    while sleep 6 && kill -0 "$parent" 2>/dev/null; do
      t=$((t + 6))
      p=$((44 + 36 * t / (t + 240)))
      progress "$p" "Сборка образов: $((t / 60)) мин $((t % 60)) с"
    done
  ) &
  tick=$!
  run "Сборка образов (3-8 минут)" docker compose build || { kill "$tick" 2>/dev/null; return 1; }
  kill "$tick" 2>/dev/null
  wait "$tick" 2>/dev/null || true
  progress 80 "Образы собраны"
  ok "Образы собраны"
}

# only now the containers are replaced: "up -d" recreates just the services whose image or settings changed
# (nginx keeps running when it did not change). The build id is passed to the backend explicitly because it
# is written to .env only after the health check.
launch() {
  step "Запуск контейнеров"
  cd "$APP_DIR"
  run "Запуск контейнеров" env APP_VERSION="$COREGSM_BUILD" docker compose up -d --remove-orphans
  if [ "$CERT_CHANGED" = 1 ] && service_running nginx-proxy; then
    docker compose exec -T nginx-proxy nginx -s reload >/dev/null 2>&1 || true
  fi
  info "Жду готовности панели…"
  local i
  for i in $(seq 1 60); do
    progress $((88 + i * 8 / 60)) "Запускаю контейнеры, жду ответа панели (${i}/60)"
    if curl -fsk --noproxy "*" --max-time 3 --resolve "${DOMAIN}:443:127.0.0.1" "https://${DOMAIN}/api/health" >/dev/null 2>&1; then
      ok "Панель отвечает"
      PANEL_OK=1
      # the previous images are now untagged (the :prev copies for rollback stay): free the disk
      docker image prune -f >/dev/null 2>&1 || true
      return 0
    fi
    sleep 3
  done
  warn "Панель не ответила за 3 минуты. Логи: cd $APP_DIR && docker compose logs --tail=100"
}

# Let's Encrypt: once after issuing, check in the BACKGROUND that renewal works through the running panel
# (webroot, as the certbot container does). The install never waits for it: the check can take minutes
# (image pull, Let's Encrypt staging, proxies). The result goes to $APP_DIR/.renewal-check and the install log.
verify_renewal() {
  [ "$CERT_ISSUED" = 1 ] && [ "$PANEL_OK" = 1 ] || return 0
  local out="$APP_DIR/.renewal-check"
  : > "$out"
  nohup setsid bash -c '
    if timeout 300 docker run --rm '"${BUILD_PROXY:+-e HTTPS_PROXY=$BUILD_PROXY}"'          -v "'"$APP_DIR"'/certbot/conf:/etc/letsencrypt" -v "'"$APP_DIR"'/certbot/www:/var/www/certbot"          certbot/certbot renew --dry-run --authenticator webroot --webroot-path /var/www/certbot >>"'"$LOGFILE"'" 2>&1; then
      echo "ok $(date -u +%FT%TZ)" > "'"$out"'"
    else
      echo "fail $(date -u +%FT%TZ)" > "'"$out"'"
    fi' >/dev/null 2>&1 &
  info "Проверка автопродления сертификата идёт в фоне (результат: cat $out)"
}

report() {
  if logo_ok; then banner; fi
  local line="════════════════════════════════════════════════════════════"
  echo -e "\n${GREEN}${line}${NC}"
  echo -e "${GREEN}  ✔  CoreGSM установлен${NC}"
  echo -e "${GREEN}${line}${NC}"
  echo -e "  ${BOLD}Панель:${NC}   ${CYAN}https://${DOMAIN}${NC}"
  if curl -fsk --noproxy "*" --max-time 5 --resolve "${DOMAIN}:443:127.0.0.1" "https://${DOMAIN}/api/setup/status" 2>/dev/null | grep -q '"needed":true'; then
    echo -e "  ${BOLD}Код установки:${NC} ${YELLOW}${SETUP_TOKEN}${NC}"
    echo -e "${GREEN}${line}${NC}"
    echo -e "  Откройте панель в браузере и пройдите первичную настройку:"
    echo -e "  введите код установки, придумайте логин и пароль администратора."
  else
    echo -e "${GREEN}${line}${NC}"
    echo -e "  Панель уже настроена: войдите под своим логином и паролем."
  fi
  echo -e "${GREEN}${line}${NC}"
  if [ "${CERT_MODE:-}" = "local" ]; then
    echo -e "  ${YELLOW}Локальный режим:${NC} сертификат самоподписанный, браузер покажет предупреждение."
    echo -e "  Нажмите «Дополнительно» → «Перейти на ${DOMAIN}»."
  fi
  if [ "${CERT_MODE:-}" = "selfsigned" ]; then
    echo -e "  ${RED}Сертификат самоподписанный${NC}: браузер покажет предупреждение."
    echo -e "  Настройте A-запись ${DOMAIN} на этот сервер и повторите: ${BOLD}sudo bash install.sh${NC}"
  fi
  echo -e "  ${BOLD}Папка установки:${NC} ${CYAN}${APP_DIR}${NC}"
  echo -e "  ${DIM}Секреты:  ${APP_DIR}/.env      Логи:  cd ${APP_DIR} && docker compose logs -f${NC}"
  echo -e "  ${DIM}Резервные копии: ${APP_DIR}/backups      Данные (база, картинки): том Docker coregsm_data${NC}"
  echo -e "  ${DIM}Управление, обновление, копии, удаление:  sudo coregsm${NC}"
  echo -e "  ${DIM}Токен Discord-бота, прокси и пароль: в панели, раздел «Настройки».${NC}\n"
}

# /usr/local/bin/coregsm (the manager, see tools/coregsm.sh), the old coregsm-update name as an alias,
# bash completion and the systemd path unit behind the panel's "Update" button.
install_manager() {
  cat > /usr/local/bin/.coregsm.new << 'MANAGER'
@@MANAGER_SCRIPT@@
MANAGER
  chmod +x /usr/local/bin/.coregsm.new
  # atomic replace: a manager that is running right now keeps reading its old file safely
  mv -f /usr/local/bin/.coregsm.new /usr/local/bin/coregsm

  printf '#!/bin/sh\nexec /usr/local/bin/coregsm update "$@"\n' > /usr/local/bin/.coregsm-update.new
  chmod +x /usr/local/bin/.coregsm-update.new
  mv -f /usr/local/bin/.coregsm-update.new /usr/local/bin/coregsm-update

  # remember where the panel lives: the manager and later installer runs read this file
  mkdir -p /etc/coregsm
  printf '%s
' "$APP_DIR" > /etc/coregsm/app_dir
  chmod 644 /etc/coregsm/app_dir

  mkdir -p /etc/bash_completion.d
  cat > /etc/bash_completion.d/coregsm << 'COMP'
_coregsm() {
  local cur="${COMP_WORDS[COMP_CWORD]}"
  if [ "$COMP_CWORD" -eq 1 ]; then
    COMPREPLY=($(compgen -W "update rollback status doctor logs start stop restart backup restore domain reset-password uninstall help" -- "$cur"))
  fi
}
complete -F _coregsm coregsm
COMP

  # the panel (container user "node", uid 1000) may only drop a request file here; root does the work
  mkdir -p "$APP_DIR/update"
  chown 1000:1000 "$APP_DIR/update"
  chmod 755 "$APP_DIR/update"

  if [ -d /run/systemd/system ]; then
    cat > /etc/systemd/system/coregsm-update.service << UNIT
[Unit]
Description=CoreGSM update (started from the web panel)

[Service]
Type=oneshot
Environment=APP_DIR=${APP_DIR}
ExecStart=/usr/local/bin/coregsm update --from-panel
TimeoutStartSec=1800
UNIT
    cat > /etc/systemd/system/coregsm-update.path << UNIT
[Unit]
Description=Watch for update requests from the CoreGSM web panel

[Path]
PathExists=${APP_DIR}/update/request
Unit=coregsm-update.service

[Install]
WantedBy=multi-user.target
UNIT
    # daily check of the certificate expiry (warns in the log and in the journal when < 14 days are left)
    cat > /etc/systemd/system/coregsm-health.service << UNIT
[Unit]
Description=CoreGSM daily health check (certificate expiry)

[Service]
Type=oneshot
Environment=APP_DIR=${APP_DIR}
ExecStart=/usr/local/bin/coregsm health
UNIT
    cat > /etc/systemd/system/coregsm-health.timer << UNIT
[Unit]
Description=CoreGSM daily health check

[Timer]
OnCalendar=*-*-* 06:00:00
RandomizedDelaySec=900
Persistent=true

[Install]
WantedBy=timers.target
UNIT
    systemctl daemon-reload
    systemctl enable --now coregsm-health.timer >/dev/null 2>&1 || warn "Не удалось включить ежедневную проверку сертификата (coregsm-health.timer)"
    systemctl enable --now coregsm-update.path >/dev/null 2>&1 \
      && ok "Команда coregsm и кнопка «Обновить» в панели включены" \
      || warn "Не удалось включить systemd-юнит coregsm-update.path: кнопка в панели работать не будет, обновляйте командой sudo coregsm update"
  else
    ok "Команда coregsm установлена"
    warn "systemd не найден: кнопка «Обновить» в панели недоступна, используйте sudo coregsm update"
  fi
}

installed_already() { [ -f "$APP_DIR/.env" ] && [ -f "$APP_DIR/docker-compose.yml" ] && [ -x /usr/local/bin/coregsm ]; }

# Rollback is possible when the previous images and the pre-update backup (taken by "coregsm update") exist.
rollback_available() {
  [ -f "$APP_DIR/.prev/src.tgz" ] || return 1
  [ -f "$APP_DIR/.prev/pre_backup" ] && [ -f "$(cat "$APP_DIR/.prev/pre_backup" 2>/dev/null)" ] || return 1
  docker images --format '{{.Repository}}:{{.Tag}}' 2>/dev/null | grep -qE '^coregsm-.*:prev$'
}

# The new build id is stamped into .env only after the panel has answered: a failed update must not look
# like a finished one (the next "coregsm update" would claim "up to date").
promote_version() {
  [ "$PANEL_OK" = 1 ] || return 0
  env_set APP_VERSION "$COREGSM_BUILD"
}

# A finished install is a successful update: tell the panel, so an old failure is not shown any more.
# Started by "coregsm update" the manager writes the status itself, after its own health check.
mark_update_done() {
  promote_version
  [ "$PANEL_OK" = 1 ] || return 0
  [ "${COREGSM_FROM_MANAGER:-0}" = 1 ] && return 0
  [ -d "$APP_DIR/update" ] || return 0
  local rb=false; rollback_available && rb=true
  printf '{"state":"done","message":"Установлена версия %s","time":%s000,"rollback_available":%s}\n' \
    "${COREGSM_BUILD:0:7}" "$(date +%s)" "$rb" > "$APP_DIR/update/status.json.tmp" 2>/dev/null \
    && mv -f "$APP_DIR/update/status.json.tmp" "$APP_DIR/update/status.json" 2>/dev/null || true
  chmod 644 "$APP_DIR/update/status.json" 2>/dev/null || true
}

main() {
  local do_install=0 arg
  for arg in "$@"; do
    case "$arg" in
      --install) do_install=1 ;;
      -h|--help)
        cat << 'HELP'
CoreGSM: установка и управление.

  bash install.sh             установить; если CoreGSM уже стоит, откроет меню управления
  bash install.sh --install   выполнить установку или переустановку без меню
  coregsm                     меню управления (после установки доступно из любой папки)

Переменные окружения: DOMAIN, LE_EMAIL, PROXY_URL, SKIP_UPDATE=1, LOCAL_MODE=1
HELP
        exit 0 ;;
      *) die "Неизвестный параметр: $arg (см. bash install.sh --help)" ;;
    esac
  done

  # On a machine that already runs CoreGSM a plain "bash install.sh" opens the management menu.
  # --install, SKIP_UPDATE=1 (older updaters, dev flows) or a non-interactive shell run the installer.
  if [ "$do_install" = 0 ] && [ -z "${SKIP_UPDATE:-}" ] && [ -t 0 ] && [ -t 1 ] && installed_already; then
    exec /usr/local/bin/coregsm
  fi

  logf "=== CoreGSM install $(date -u '+%F %T') UTC, build $COREGSM_BUILD ==="

  banner
  choose_install_dir
  preflight
  setup_proxy
  system_update
  base_packages
  install_docker
  collect_input
  setup_firewall
  step "Создание файлов проекта в $APP_DIR"
  generate_project
  ok "Файлы проекта созданы"
  write_env
  install_manager
  # images first (the old version keeps serving), then the certificate, then the containers are replaced
  build_images
  issue_certificate
  env_set CERT_MODE "$CERT_MODE"
  launch
  verify_renewal
  mark_update_done
  report
}

main "$@"
